import csv,json,statistics
import numpy as np
from pathlib import Path
P=Path(__file__).resolve().parent
s=json.loads((P/'actual_policy_summary.json').read_text());old=json.loads((P/'hnsw_summary.json').read_text())
rows=list(csv.DictReader((P/'actual_policy.csv').open()));cohorts=[]
rng=np.random.default_rng(20261023)
for h in [1,2,3,4]:
 for L in [64,256,1024,4096]:
  a=[r for r in rows if int(r['h'])==h and int(r['budget'])==L]
  b=[r for r in rows if int(r['h'])==h and r['method']==s['strongest_mean_baseline']]
  qids=sorted(set(int(r['qid']) for r in a));aa=np.array([statistics.mean(float(r['ms']) for r in a if int(r['qid'])==q) for q in qids]);bb=np.array([statistics.mean(float(r['ms']) for r in b if int(r['qid'])==q) for q in qids]);ix=rng.integers(0,len(qids),(2000,len(qids)));ci=np.quantile(aa[ix].mean(1)/bb[ix].mean(1),[.025,.975])
  cohorts.append(dict(h=h,budget=L,policy_mean_ms=float(aa.mean()),baseline_mean_ms=float(bb.mean()),recall=statistics.mean(float(r['recall']) for r in a),mean_ratio=float(aa.mean()/bb.mean()),bootstrap95ci_lo=float(ci[0]),bootstrap95ci_hi=float(ci[1])))
with (P/'actual_policy_cohorts.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(cohorts[0]));w.writeheader();w.writerows(cohorts)
lines=['# Actual early-return policy follow-up','','This report supersedes the underfill-policy timing interpretation in REAL_EXPERIMENT_REPORT.md. The original hnsw_raw.csv always executed exact repair to measure its incremental cost. Its policy_ms values therefore reconstruct a policy cost by adding measured components; they were not single-timer executions of an early-return branch. Those records remain valid for the explicitly analytical independent-fallback sweep and prefix quality analysis.','','The additional benchmark_actual_policy.py actually returns immediately when k legal prefix objects are available and runs forward repair only otherwise. One outer timer measures the full request, including function return and release of request-local state. It uses the same saved HNSW index, queries and budgets, with CPU 4 affinity, one HNSW/BLAS thread and GC disabled. One complete warmup pass precedes three measured repetitions, each with randomized query and method/budget orders. All exact controls use the same float64 scalar dot(delta,delta) kernel, with identifier tie-breaking.','','ForwardSort sorts all eligible objects; ForwardTopKHeap uses heapq.nsmallest; ForwardTopKPartition uses argpartition to find the kth distance, keeps every boundary tie, and sorts the small retained set with ID tie-breaking. The strongest mean baseline in this matched run is '+s['strongest_mean_baseline']+'.','','| Method | Mean ms | Median ms | IQR ms | p95 ms |','|---|---:|---:|---:|---:|']
for name,v in s['baselines'].items():lines.append(f"|{name}|{v['mean']:.6f}|{v['median']:.6f}|{v['iqr']:.6f}|{v['p95']:.6f}|")
lines+=['','| L | Actual mean ms | Reconstructed earlier ms | Recall | Fallback rate | Actual / strongest baseline | 95% paired-query bootstrap ratio CI |','|---:|---:|---:|---:|---:|---:|---|']
for a,b in zip(s['budgets'],old['budgets']):lines.append(f"|{a['budget']}|{a['ms']['mean']:.6f}|{b['underfill_policy_ms']:.6f}|{a['recall']:.4f}|{a['fallback_rate']:.4f}|{a['mean_ratio_to_strongest']:.4f}|[{a['paired_bootstrap95ci'][0]:.4f}, {a['paired_bootstrap95ci'][1]:.4f}]|")
lines+=['','The actual run performs 960 policy executions and 720 exact-baseline executions. All repaired and exact answers match an independently computed edge-table oracle, and all early answers contain k legal objects. At L=4096, queries 65 and 73 still have recall 0.9 despite satisfying the count rule. Empty truth does not occur.','','The two runs use the same input and index but differ in instrumentation: the component run counted graph work and measured separate intervals; the actual policy omits operation counters. Therefore differences between reconstructed and actual times are descriptive across separate runs, not paired instrumentation-overhead estimates. The actual matched control results should be used for the stopping-policy comparison in the manuscript. The original independent-p curve remains a component-based analytical expectation, not an actual stopping-policy timing.','','Reproduce and audit:','','```text','python benchmark_actual_policy.py','python audit_real.py','python analyze_actual_policy.py','```']
v=next(c for c in cohorts if c['h']==4 and c['budget']==64)
lines+=['',f"Actual h=4, L=64 subgroup: policy {v['policy_mean_ms']:.6f} ms, matched heap baseline {v['baseline_mean_ms']:.6f} ms, policy/baseline ratio {v['mean_ratio']:.4f} with 95% paired-query bootstrap CI [{v['bootstrap95ci_lo']:.4f}, {v['bootstrap95ci_hi']:.4f}]. This small subgroup does not establish a reliable crossover."]
(P/'ACTUAL_POLICY_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
print('Actual policy report and stratified measurements saved.')
